//! 🧪️ Production export consumes original Drawing issuer reads without a synthetic provider or inline content mirror.
use super::*;
use semio_framework_io_ports::{ChildAdmissionRead,erase_child_admission_source};
use semio_framework_value::retained_clone::RetainedCloneGrant;
use semio_s_artifact_draw_drawing_model::snapshot::DrawingSnapshot;
use semio_s_artifact_draw_drawing_editor::child_editor::DRAWING_CHILD_VECTOR_READ;
#[test]fn layout_plan_retains_actual_drawing_sources_and_publishes_one_item_per_turn(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../🎬️scene/🧵️drawing/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let transport:serde_json::Value=serde_json::from_str(include_str!("../../../../../🧬️schema/🧬️mutations/🖊️set-page-background-drawing/🧪️tests/🔣️transport.json")).unwrap();
 for row in corpus["cases"].as_array().unwrap(){let mut snapshot=semio_s_artifact_layout_layout_model::io::text::snapshot::snapshot_wire_codec::default_document();snapshot.pages[0].frames.clear();snapshot.pages[0].parent_page_id=None;snapshot.pages[0].layers.clear();snapshot.background_drawing=Some(semio_framework_pack_json::from_json_str(&transport["cases"][0]["input"]["SetPageBackgroundDrawing"]["drawing"].to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap());
  let actual:DrawingSnapshot=semio_framework_pack_json::from_json_str(&row["content"].to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let payload=Arc::new(actual);let registry=store::os_store::snapshot_read::SnapshotReadRegistryHandle::new();let lease=registry.try_issue(Arc::clone(&payload)).unwrap_or_else(|_|panic!("actual original child registry"));let read=store::os_store::snapshot_read::ErasedSnapshotRead::new(Arc::clone(&payload),lease).try_into_typed::<DrawingSnapshot>().unwrap_or_else(|_|panic!("actual typed Drawing original"));let(mut source,_)=read.admit_retained_clone_source(LAYOUT_EXPORT_FIXTURE_TURN).unwrap_or_else(|_|panic!("original Drawing source birth"));
  let operation=Operation::new(semio_framework_job::OperationId(94),semio_framework_job::RevisionId(29),semio_framework_job::Generation(3),17);let request=LayoutExportRequest{kind:LayoutExportKind::Svg,page_id:Some(snapshot.pages[0].id.clone()),snapshot:Arc::new(snapshot),preflight_json:None,parent_document_id:"planning".into(),canonical_base_revision_hex:"29".repeat(32)};let supplier=Arc::clone(&request.snapshot);let mut job=LayoutExportJob::from_admitted(operation,(operation.operation,operation.generation),request,ArtifactOutputChunks::new(MAX_LAYOUT_EXPORT_OUTPUT_BYTES));let mut caller=layout_export_fixture_caller(operation,operation.generation);let mut refused=false;
  for _ in 0..1000000{if job.stage==ExportStage::BeginEncode{break}let before=job.pdf_items.len();let borrowed=ChildAdmissionRead{source:erase_child_admission_source(source.borrow(),0x44524157),admitter:DRAWING_CHILD_VECTOR_READ.admission,vector:DRAWING_CHILD_VECTOR_READ.vector};let next=caller.turn(LAYOUT_EXPORT_FIXTURE_TURN,|cx|Ok(job.advance_original_work(cx,Some(&borrowed)))).unwrap();match next{Ok(_)=>{},Err(_)=>{refused=true;break}}assert!(job.pdf_items.len()-before<=1);assert!(Arc::ptr_eq(&job.request.as_ref().unwrap().snapshot,&supplier));assert!(job.slot.publication.is_none());}
  let kinds=row["expected"]["primitiveKinds"].as_array().unwrap();let requires_resolution=kinds.iter().any(|kind|kind.as_str()==Some("resolve"));assert_eq!(refused,requires_resolution,"{}",row["name"]);if !refused{assert_eq!(job.pdf_items.iter().filter(|item|matches!(item,PdfItem::DrawingPath{..})).count(),kinds.iter().filter(|kind|kind.as_str()==Some("beginPath")).count());assert_eq!(job.pdf_pages.len(),1);assert_eq!(job.pdf_pages[0].items,job.pdf_items.len());}InteractiveJob::begin_close(&mut job);for _ in 0..1000000{if InteractiveJob::terminal_is_empty(&job){break}caller.turn(LAYOUT_EXPORT_FIXTURE_TURN,|cx|Ok(InteractiveJob::close_step(&mut job,cx))).unwrap().unwrap();}assert!(InteractiveJob::terminal_is_empty(&job));assert!(job.drawing_consumers_terminal_is_empty());caller.retire(LAYOUT_EXPORT_FIXTURE_STOCK);
  while !source.terminal_is_empty(){let d=source.next_close_demand(LAYOUT_EXPORT_FIXTURE_TURN.maximum_copy_bytes).unwrap();source.close_step(RetainedCloneGrant{maximum_items:64,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}).unwrap();}assert!(registry.terminal_is_empty());drop(payload);let mut close=Some(store::os_store::snapshot_read::SnapshotReadRegistryAliasRetirement::new(registry));while close.is_some(){store::os_store::snapshot_read::snapshot_registry_alias_close_step(&mut close,LAYOUT_EXPORT_FIXTURE_TURN).unwrap();}
 }
}
